function rotr(x, n) { return (x >>> n) | (x << (32 - n)); }

function sha256(msg) {
  const bytes = Array.from(msg);
  const len = bytes.length;
  bytes.push(0x80);
  while (bytes.length % 64 !== 56) bytes.push(0);
  const hi = Math.floor(len / 0x20000000);
  const lo = (len << 3) >>> 0;
  bytes.push((hi >>> 24) & 255, (hi >>> 16) & 255, (hi >>> 8) & 255, hi & 255,
    (lo >>> 24) & 255, (lo >>> 16) & 255, (lo >>> 8) & 255, lo & 255);
  let h = [0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19];
  const w = new Array(64);
  for (let i = 0; i < bytes.length; i += 64) {
    for (let t = 0; t < 16; t++) {
      w[t] = ((bytes[i + 4 * t] << 24) | (bytes[i + 4 * t + 1] << 16) | (bytes[i + 4 * t + 2] << 8) | bytes[i + 4 * t + 3]) >>> 0;
    }
    for (let t = 16; t < 64; t++) {
      const s0 = rotr(w[t - 15], 7) ^ rotr(w[t - 15], 18) ^ (w[t - 15] >>> 3);
      const s1 = rotr(w[t - 2], 17) ^ rotr(w[t - 2], 19) ^ (w[t - 2] >>> 10);
      w[t] = (w[t - 16] + s0 + w[t - 7] + s1) >>> 0;
    }
    let [a, b, c, d, e, f, g, hh] = h;
    for (let t = 0; t < 64; t++) {
      const S1 = rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25);
      const ch = (e & f) ^ (~e & g);
      const t1 = (hh + S1 + ch + K256[t] + w[t]) >>> 0;
      const S0 = rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22);
      const maj = (a & b) ^ (a & c) ^ (b & c);
      const t2 = (S0 + maj) >>> 0;
      hh = g; g = f; f = e; e = (d + t1) >>> 0; d = c; c = b; b = a; a = (t1 + t2) >>> 0;
    }
    h = [h[0] + a, h[1] + b, h[2] + c, h[3] + d, h[4] + e, h[5] + f, h[6] + g, h[7] + hh].map((x) => x >>> 0);
  }
  const out = [];
  for (const x of h) out.push((x >>> 24) & 255, (x >>> 16) & 255, (x >>> 8) & 255, x & 255);
  return out;
}

function toHex(bytes) {
  let s = '';
  for (const b of bytes) s += (b < 16 ? '0' : '') + b.toString(16);
  return s;
}

// key: string. msg: array or Uint8Array of bytes. Returns hex string.
function hmacSha256Hex(key, msg) {
  let k = utf8(String(key));
  if (k.length > 64) k = sha256(k);
  while (k.length < 64) k.push(0);
  const ipad = k.map((b) => b ^ 0x36);
  const opad = k.map((b) => b ^ 0x5c);
  const inner = sha256(ipad.concat(Array.from(msg)));
  return toHex(sha256(opad.concat(inner)));
}

// Compares two strings without returning early on the first mismatch.
function safeEqual(a, b) {
  a = String(a); b = String(b);
  let diff = a.length ^ b.length;
  const n = Math.max(a.length, b.length);
  for (let i = 0; i < n; i++) diff |= (a.charCodeAt(i) || 0) ^ (b.charCodeAt(i) || 0);
  return diff === 0;
}

// Normalizers and string similarity. Comparing normalized values prevents churn from formatting
// differences ("(410) 555-0101" vs "410-555-0101") that are not real data differences.

function normName(s) {
  let t = String(s == null ? '' : s);
  if (t.includes(',')) { const [last, first] = t.split(','); t = (first || '') + ' ' + last; } // "Smith, John"
  return t.toLowerCase().normalize('NFKD').replace(/[̀-ͯ]/g, '')
    .replace(/[^a-z0-9 ]/g, ' ').replace(/\b(mr|mrs|ms|dr|jr|sr|ii|iii)\b/g, ' ').replace(/\s+/g, ' ').trim();
}

function normEmail(s) {
  const t = String(s == null ? '' : s).trim().toLowerCase();
  const at = t.lastIndexOf('@');
  if (at < 1) return '';
  let local = t.slice(0, at).split('+')[0];
  const domain = t.slice(at + 1);
  if (domain === 'gmail.com' || domain === 'googlemail.com') local = local.replace(/\./g, '');
  return local + '@' + domain;
}

function normPhone(s) {
  let d = String(s == null ? '' : s).replace(/\D/g, '');
  if (d.length === 11 && d[0] === '1') d = d.slice(1);
  return d.length >= 10 ? d.slice(-10) : d.length >= 7 ? d : '';
}

function normPostal(s) { return String(s == null ? '' : s).toUpperCase().replace(/[^A-Z0-9]/g, '').slice(0, 5); }

function jaroWinkler(a, b) {
  if (a === b) return a.length ? 1 : 0;
  if (!a.length || !b.length) return 0;
  const range = Math.max(0, Math.floor(Math.max(a.length, b.length) / 2) - 1);
  const am = new Array(a.length).fill(false), bm = new Array(b.length).fill(false);
  let m = 0;
  for (let i = 0; i < a.length; i++) {
    for (let j = Math.max(0, i - range); j < Math.min(b.length, i + range + 1); j++) {
      if (!bm[j] && a[i] === b[j]) { am[i] = bm[j] = true; m++; break; }
    }
  }
  if (!m) return 0;
  let t = 0, k = 0;
  for (let i = 0; i < a.length; i++) { if (am[i]) { while (!bm[k]) k++; if (a[i] !== b[k]) t++; k++; } }
  const jaro = (m / a.length + m / b.length + (m - t / 2) / m) / 3;
  let p = 0;
  while (p < 4 && p < a.length && p < b.length && a[p] === b[p]) p++;
  return jaro + p * 0.1 * (1 - jaro);
}

// Field-level diff with per-field source of truth, plus the blast-radius guard.
// Needs hmac.js and strings.js inlined above it in n8n.

// Which system owns which field. The owner's value overwrites the other system's.
const CRM_OWNS = [
  { crm: 'full_name', bill: 'name', same: (a, b) => normName(a) === normName(b) },
  { crm: 'email', bill: 'email', same: (a, b) => normEmail(a) === normEmail(b) },
  { crm: 'phone', bill: 'phone', same: (a, b) => normPhone(a) === normPhone(b) },
  { crm: 'postal_code', bill: 'postal', same: (a, b) => normPostal(a) === normPostal(b) },
];
const BILLING_OWNS = [
  { crm: 'plan', bill: 'plan', same: (a, b) => String(a || '').trim().toLowerCase() === String(b || '').trim().toLowerCase() },
  { crm: 'status', bill: 'status', same: (a, b) => String(a || '').trim().toLowerCase() === String(b || '').trim().toLowerCase() },
];

const BILLING_BASE = 'https://billing.example.invalid/api/accounts/';
const CRM_BASE = 'https://crm.example.invalid/api/contacts/';
const GUARD_RATIO = 0.2;   // refuse to apply if more than 20% of matched records would change
const GUARD_MIN = 10;      // ...but always allow at least this many

const blank = (v) => v == null || String(v).trim() === '';

function stable(o) { return JSON.stringify(Object.keys(o).sort().map((k) => [k, o[k]])); }

function makeAction(target, recordId, patch, reason) {
  const key = toHex(sha256(utf8(target + '|' + recordId + '|' + stable(patch))));
  return {
    target, record_id: recordId, patch, reason, idempotency_key: key, method: 'PATCH',
    url: (target === 'billing' ? BILLING_BASE : CRM_BASE) + encodeURIComponent(recordId),
  };
}

function planActions(matched, crmById, billById) {
  const actions = []; const skippedBlank = [];
  for (const m of matched) {
    const c = crmById[m.crm_id], b = billById[m.billing_id];
    if (!c || !b) continue;
    const toBilling = {}, toCrm = {};
    for (const f of CRM_OWNS) {
      if (f.same(c[f.crm], b[f.bill])) continue;
      if (blank(c[f.crm])) { skippedBlank.push({ crm_id: c.id, field: f.crm }); continue; } // never wipe data with an empty value
      toBilling[f.bill] = c[f.crm];
    }
    for (const f of BILLING_OWNS) {
      if (f.same(c[f.crm], b[f.bill])) continue;
      if (blank(b[f.bill])) { skippedBlank.push({ billing_id: b.id, field: f.bill }); continue; }
      toCrm[f.crm] = b[f.bill];
    }
    if (c.billing_id !== b.id) toCrm.billing_id = b.id; // backfill the link
    if (Object.keys(toBilling).length) actions.push(makeAction('billing', b.id, toBilling, 'crm_owns:' + Object.keys(toBilling).join(',')));
    if (Object.keys(toCrm).length) actions.push(makeAction('crm', c.id, toCrm, 'billing_owns:' + Object.keys(toCrm).join(',')));
  }
  return { actions, skippedBlank };
}

function guardLimit(matchedCount) { return Math.max(GUARD_MIN, Math.ceil(GUARD_RATIO * matchedCount)); }

const item = $input.first().json;
const crmById = Object.fromEntries(item.crm.map((r) => [r.id, r]));
const billById = Object.fromEntries(item.billing.map((r) => [r.id, r]));
const { actions, skippedBlank } = planActions(item.finalMatched, crmById, billById);
const limit = guardLimit(item.finalMatched.length);
const guardTripped = actions.length > limit && !item.runCtx.force;
const apply = actions.length > 0 && !item.runCtx.dryRun && !guardTripped;
const byMethod = {};
for (const m of item.finalMatched) byMethod[m.method] = (byMethod[m.method] || 0) + 1;
const stats = {
  crmFetched: item.crm.length, billingFetched: item.billing.length, matched: item.finalMatched.length, byMethod,
  unmatchedCrm: item.match.unmatchedCrm.length, orphanBilling: item.match.orphanBilling.length, conflicts: item.match.conflicts.length,
  adjudication: item.adjudication, plannedActions: actions.length, skippedBlankFields: skippedBlank.length, guardLimit: limit,
  driftPct: item.finalMatched.length ? Math.round(1000 * new Set(actions.map((a) => a.record_id)).size / item.finalMatched.length) / 10 : 0,
};
return [{ json: { runCtx: item.runCtx, actions, apply, guardTripped, stats } }];

const now = Date.now();
const sd = $getWorkflowStaticData('global');
const plan = $('Plan Actions').first().json;
const results = [];
for (const [split, apply] of [['Split Billing Updates', 'Apply to Billing'], ['Split CRM Updates', 'Apply to CRM']]) {
  let sent = []; let resp = [];
  try { sent = $(split).all(); } catch (e) {}
  try { resp = $(apply).all(); } catch (e) {}
  sent.forEach((s, i) => {
    const r = resp[i] && resp[i].json;
    const err = !r ? 'no response' : r.error ? (r.error.message || JSON.stringify(r.error)) : null;
    results.push({ target: s.json.target, record_id: s.json.record_id, fields: Object.keys(s.json.patch), key: s.json.idempotency_key, error: err ? String(err).slice(0, 200) : null });
  });
}
const failed = results.filter((r) => r.error);
// Dead letter keeps ids, field names and the error only. Never field values.
sd.deadLetter = (sd.deadLetter || []).concat(failed.map((f) => ({ at: new Date(now).toISOString(), target: f.target, record_id: f.record_id, fields: f.fields, error: f.error }))).slice(-200);
let status = 'success';
if (plan.runCtx.dryRun) status = 'dry_run';
else if (plan.guardTripped) status = 'halted_guard';
else if (failed.length) status = 'partial';
const summary = { runId: plan.runCtx.runId, status, startedAt: plan.runCtx.startedAt, finishedAt: new Date(now).toISOString(),
  applied: results.length - failed.length, failed: failed.length, ...plan.stats, reviewQueue: (sd.review || []).length };
sd.lastRun = summary;
if (sd.lock && sd.lock.runId === plan.runCtx.runId) sd.lock = null;
const lines = [
  '*Reconciliation run ' + summary.runId + '*: ' + status.toUpperCase() + (plan.runCtx.dryRun ? ' (no changes written)' : ''),
  'Records: CRM ' + summary.crmFetched + ', billing ' + summary.billingFetched + ', matched ' + summary.matched + ', drift ' + summary.driftPct + '%',
  'Planned ' + summary.plannedActions + ', applied ' + summary.applied + ', failed ' + summary.failed,
  'Needs attention: review ' + summary.reviewQueue + ', conflicts ' + summary.conflicts + ', unmatched CRM ' + summary.unmatchedCrm + ', orphan billing ' + summary.orphanBilling,
];
if (plan.guardTripped) lines.push('HALTED: ' + summary.plannedActions + ' changes exceeds the safety limit of ' + summary.guardLimit + '. Re-run with force=true after checking the data.');
return [{ json: { report: summary, notify: { text: lines.join('\n') } } }];

const sd = $getWorkflowStaticData('global');
const b = ($input.first().json || {}).body || {};
const bad = (code, status) => [{ json: { httpCode: code, response: { status } } }];
if (typeof b.crm_id !== 'string' || typeof b.billing_id !== 'string' || (b.decision !== 'link' && b.decision !== 'reject')) return bad(400, 'invalid_request');
const entry = (sd.review || []).find((r) => r.crm_id === b.crm_id && r.billing_id === b.billing_id);
if (!entry) return bad(404, 'not_in_review_queue');
sd.links = sd.links || {}; sd.rejected = sd.rejected || {};
if (b.decision === 'link') sd.links[b.crm_id] = { billing_id: b.billing_id, method: 'human', at: new Date().toISOString() };
else sd.rejected[b.crm_id + '|' + b.billing_id] = new Date().toISOString();
sd.review = sd.review.filter((r) => r !== entry);
return [{ json: { httpCode: 200, response: { status: 'recorded', decision: b.decision } } }];
